from __future__ import annotations

from ..release import ReleaseContext


def release_gates_markdown(context: ReleaseContext) -> str:
    verified = sum(gate.status == "verified" for gate in context.gates)
    published = context.target.state == "published-arch-release"
    lines = [
        "# Verification Summary",
        "",
        "> Generated by `./hfx generate`. Do not edit manually.",
        "",
        f"HyperFlux Next `{context.target.product_version}-{context.target.package_release}` "
        f"has `{verified}` verified technical gates. "
        + (
            "The Arch release is published through a signed project-operated Arch repository, "
            "not an official Arch Linux repository."
            if published
            else f"This candidate is not published; `{context.published_release}` remains "
            "the published Arch release."
            if context.published_release
            else "Publication remains separately locked."
        ),
        "",
        "| Check | Result | Evidence |",
        "| --- | --- | --- |",
    ]
    for gate in context.gates:
        evidence = ", ".join(f"[`{path}`](../../{path})" for path in gate.evidence)
        result = "verified" if gate.status == "verified" else "not published"
        lines.append(f"| {gate.title} | **{result}** | {evidence} |")
    lines.extend(
        [
            "",
            "## Publication Boundary",
            "",
            (
                "This release was published after the technical gates passed. "
                "It is served from a signed project-operated Arch repository, "
                "not an official Arch Linux repository. "
                "The repository signs packages and repository metadata."
                if published
                else "A passing build, test, package, or hardware check does not publish this "
                "candidate. The published release, its version tag, and the signed repository "
                "stay unchanged until the candidate is separately released."
                if context.published_release
                else "A passing build, test, package, or hardware check does not create a release. "
                "No version tag, release artifact, package channel, or signing key is published."
            ),
            "",
        ]
    )
    return "\n".join(lines)
